/**
 * The browser solve must agree with the Python solve to floating-point noise.
 *
 * Both read frontend/test/fixtures.json, which is generated by
 * backend/tests/generate_fixtures.py and guarded by a pytest that fails if the
 * Python side changes without the fixtures being regenerated.
 */

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import test from 'node:test';

const here = dirname(fileURLToPath(import.meta.url));
const solve = await import(join(here, '..', '.test-build', 'solve.js'));
const { cases } = JSON.parse(readFileSync(join(here, 'fixtures.json'), 'utf8'));

const TOL = 1e-9;

function closeTo(actual, expected, tol, what) {
  assert.ok(
    Math.abs(actual - expected) <= tol,
    `${what}: got ${actual}, expected ${expected} (tol ${tol})`,
  );
}

function arrayCloseTo(actual, expected, tol, what) {
  assert.equal(actual.length, expected.length, `${what}: length`);
  actual.forEach((v, i) => closeTo(v, expected[i], tol, `${what}[${i}]`));
}

for (const c of cases) {
  test(`solve matches Python: ${c.name}`, () => {
    const result = solve.solveFromControlPoints(
      c.width,
      c.height,
      c.controlPoints,
      c.cameraHeight,
    );
    assert.equal(result.error, null);
    const cam = result.camera;
    const want = c.expected.camera;

    arrayCloseTo(
      result.vanishingPoints.axisA,
      c.expected.vanishingPoints.axisA,
      1e-7,
      'vp A',
    );
    arrayCloseTo(
      result.vanishingPoints.axisB,
      c.expected.vanishingPoints.axisB,
      1e-7,
      'vp B',
    );

    closeTo(cam.focal_px, want.focal_px, 1e-7, 'focal');
    closeTo(cam.vfovDeg, want.vfovDeg, 1e-9, 'vfov');
    closeTo(cam.aspect, want.aspect, 1e-12, 'aspect');
    arrayCloseTo(cam.principal_point, want.principal_point, TOL, 'principal point');
    arrayCloseTo(cam.rotation, want.rotation, 1e-9, 'rotation');
    arrayCloseTo(
      cam.rotationCameraToWorld,
      want.rotationCameraToWorld,
      1e-9,
      'rotation camera->world',
    );
    arrayCloseTo(cam.position, want.position, 1e-8, 'position');
  });

  test(`projection matches Python: ${c.name}`, () => {
    const cam = solve.solveFromControlPoints(
      c.width,
      c.height,
      c.controlPoints,
      c.cameraHeight,
    ).camera;
    for (const item of c.expected.projections) {
      const p = solve.project(cam, item.point);
      assert.equal(p.visible, item.visible, `visibility of ${item.point}`);
      if (item.visible) {
        arrayCloseTo([p.u, p.v], item.uv, 1e-6, `projection of ${item.point}`);
      }
    }
  });

  test(`ground unprojection matches Python: ${c.name}`, () => {
    const cam = solve.solveFromControlPoints(
      c.width,
      c.height,
      c.controlPoints,
      c.cameraHeight,
    ).camera;
    for (const item of c.expected.ground) {
      const point = solve.groundPointAt(cam, item.pixel[0], item.pixel[1]);
      if (item.point === null) {
        assert.equal(point, null, `pixel ${item.pixel} should miss the ground`);
      } else {
        arrayCloseTo(point, item.point, 1e-7, `ground point at ${item.pixel}`);
        closeTo(point[1], 0, 1e-9, 'ground points sit on y = 0');
      }
    }
  });

  test(`horizon and grid match Python: ${c.name}`, () => {
    const cam = solve.solveFromControlPoints(
      c.width,
      c.height,
      c.controlPoints,
      c.cameraHeight,
    ).camera;
    closeTo(solve.horizonY(cam, 0), c.expected.horizon[0], 1e-7, 'horizon at u=0');
    closeTo(solve.horizonY(cam, c.width), c.expected.horizon[1], 1e-7, 'horizon at u=W');

    const grid = solve.groundGridSegments(cam, 6, 2);
    assert.equal(grid.length, c.expected.gridPolylineCount, 'polyline count');
    if (c.expected.gridFirstPolyline) {
      assert.equal(grid[0].length, c.expected.gridFirstPolyline.length, 'first polyline length');
      grid[0].forEach((p, i) =>
        arrayCloseTo(p, c.expected.gridFirstPolyline[i], 1e-6, `grid point ${i}`),
      );
    }
  });
}

test('an impossible vanishing-point pair is reported, not guessed', () => {
  const result = solve.solveCamera(
    1000,
    800,
    [900, 400],
    [1200, 401],
    [500, 700],
    1.6,
  );
  assert.equal(result.camera, null);
  assert.match(result.error, /not consistent with a real camera/);
});

test('parallel control lines are reported', () => {
  const result = solve.solveFromControlPoints(
    1000,
    800,
    {
      axisA: [
        [[0, 0], [100, 0]],
        [[0, 50], [100, 50]],
      ],
      axisB: [
        [[0, 0], [0, 100]],
        [[50, 0], [50, 100]],
      ],
      origin: [500, 700],
    },
    1.6,
  );
  assert.equal(result.camera, null);
  assert.match(result.error, /parallel/);
});

test('an origin above the horizon is reported', () => {
  const c = cases[0];
  const result = solve.solveFromControlPoints(
    c.width,
    c.height,
    { ...c.controlPoints, origin: [c.width / 2, 40] },
    c.cameraHeight,
  );
  assert.equal(result.camera, null);
  assert.match(result.error, /below the horizon/);
});

test('rotation is orthonormal and right handed', () => {
  for (const c of cases) {
    const m = solve.solveFromControlPoints(
      c.width,
      c.height,
      c.controlPoints,
      c.cameraHeight,
    ).camera.rotation;
    const row = (i) => [m[i * 3], m[i * 3 + 1], m[i * 3 + 2]];
    for (let i = 0; i < 3; i += 1) {
      for (let j = 0; j < 3; j += 1) {
        closeTo(solve.dot(row(i), row(j)), i === j ? 1 : 0, 1e-9, `R R^T [${i}][${j}]`);
      }
    }
    const det =
      m[0] * (m[4] * m[8] - m[5] * m[7]) -
      m[1] * (m[3] * m[8] - m[5] * m[6]) +
      m[2] * (m[3] * m[7] - m[4] * m[6]);
    closeTo(det, 1, 1e-9, 'det(R)');
  }
});
